        timing=new LyricsTiming(new LyricsStageView.Clock(){public long position(){PlaybackService.Snapshot state=host.state();return state==null?0:state.position;}public boolean playing(){PlaybackService.Snapshot state=host.state();return state!=null&&state.playing;}public void seek(long value){PlaybackService.Snapshot state=host.state();if(state!=null&&state.ready&&state.uri.equals(uri)&&(lyricGestureGeneration<0||(lyricGestureGeneration==state.generation&&lyricGestureUri.equals(state.uri))))host.seek((int)Math.min(Integer.MAX_VALUE,Math.max(0,value)));}},activity.getSharedPreferences("library",0));
