        setOnShowListener(d->{prefs.registerOnSharedPreferenceChangeListener(preferenceListener);applyLyricAppearance();getWindow().setLayout(-1,-1);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION);refresh();handler.removeCallbacks(tick);handler.post(tick);if(!reduceMotion){body.setAlpha(0);body.setTranslationY(dp(12));body.animate().alpha(1).translationY(0).setDuration(220).start();}});
